def header(active):
    links="".join(f'<a href="{u}" class="{"active" if u==active else ""}">{t}</a>' for u,t in NAV)
    about_active="active" if active=="about.html" else ""
    about=f'''<div class="nav-dropdown"><a href="about.html" class="dropdown-toggle {about_active}">About</a><div class="dropdown-menu"><a href="about.html#about-us">About Us</a><a href="about.html#founder">About the Founder</a></div></div>'''
    contact=f'<a href="contact.html" class="{"active" if active=="contact.html" else ""}">Contact</a>'
    return f'''<div class="topbar"><div class="container"><span>Serious Training. Serious Results.</span><a href="tel:18664364959">(866) 436-4959</a></div></div><header class="site-header"><div class="container nav"><a href="index.html"><img class="logo" src="assets/lorenzo-logo-transparent.png" alt="Lorenzo's Dog Training Team"></a><nav class="nav-links" id="navLinks">{links}{about}{contact}<a class="btn btn-red" href="contact.html">Book Evaluation</a></nav><button class="mobile-toggle" aria-controls="navLinks" aria-expanded="false">Menu</button></div></header>'''
